import{z as o,x as l,o as t,c as s,q as B,j as A,D as E,d as r,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"条件因子深化","description":"","frontmatter":{"title":"条件因子深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-conditional-deep.md","filePath":"quant/fz-conditional-deep.md","lastUpdated":1791413859000}'),d={name:"quant/fz-conditional-deep.md"};function _(p,a,C,m,h,f){const e=l("Mermaid");return t(),s("div",null,[a[2]||(a[2]=B('<h1 id="条件因子深化" tabindex="-1">条件因子深化 <a class="header-anchor" href="#条件因子深化" aria-label="Permalink to &quot;条件因子深化&quot;">​</a></h1><div class="epigraph"><p>无条件模型把时变压进 α：载荷随状态变、溢价随状态变，两者在平均里互相抵消或互相伪装。条件化的本质是把协方差项显式建模，而不是任它掉进定价误差。</p><footer>—— 据 Cochrane, Asset Pricing, 2001；Lettau &amp; Ludvigson, Journal of Political Economy, 2001 整理</footer></div><p><a href="/quant/fz-macro-style">上一课</a>末尾把风格收益对宏观状态回归，得到条件刻画——那是描述版。本课把条件化写成模型：载荷与溢价随状态变量变化时，无条件检验为什么系统性失真，条件假设怎么变成可检验的回归，工程上怎么构造条件因子而不掉进未来函数。<a href="/quant/conditional-capm">条件 CAPM</a> 与<a href="/quant/time-varying-rp">风险溢价时变</a>讲过基础设定；本课深化到管理组合技巧与载荷条件化的工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无条件因子模型假设 \\(E[R_i]=\\beta_i^\\top\\lambda\\)，\\(\\beta\\) 与 \\(\\lambda\\) 都是常数。实际上两者都随状态移动：杠杆约束紧的市场里 β 的风险价格高，衰退逼近时防御家族的溢价抬升。把时变硬压进无条件矩，误差不是零均值的：条件模型的无条件含义是 \\(E[R_i]=\\bar\\beta^\\top\\bar\\lambda+\\mathrm{Cov}(\\beta_t,\\lambda_t)\\)，最后一项是被丢掉的时变结构——它会被误记为定价误差。于是出现两种假象：不存在的因子因为时变「显著」，真因子因为时变被无条件检验抹平。缺口是把条件化写成回归能检验的形状。</p><p><span class="marginnote">术语翻译：条件化就是「让模型的参数跟着状态走」——β 和风险价格不再固定为常数，而是状态变量 \\(z_t\\) 的函数；无条件模型则把一切平均掉。类比体温：全年平均 36.5 度不代表可以按平均穿衣，发烧日的暴露要单独建模。</span></p><h3 id="管理组合技巧" tabindex="-1">管理组合技巧 <a class="header-anchor" href="#管理组合技巧" aria-label="Permalink to &quot;管理组合技巧&quot;">​</a></h3><p><span class="marginnote">Cochrane 的技巧：若期望收益随状态 \\(z_t\\) 线性变化，把交互项 \\(z_t\\cdot f_t\\) 当作新因子加入因子集，条件模型就变成一个更大的无条件模型——「要不要条件化」变成「交互项有没有溢价」，仍用 FM/时序回归检验。代价：每个候选 \\(z\\) 都是一次新试验。</span></p><p>设状态变量 \\(z_t\\) 在 \\(t\\) 期期初已知。若载荷随 \\(z_t\\) 线性变化，则收益的条件期望可以写成 \\(\\beta_i^\\top\\lambda+z_t\\cdot(\\delta_i^\\top\\lambda)\\) 的形式——等价于在因子集中加入交互因子 \\(z_t f_t\\)，各资产对它的载荷是 \\(\\delta_i\\)。检验条件模型就是检验交互项的风险价格是否非零，全部仍在标准框架内。这是条件化最干净的可检验形式。策略侧的对应物是条件构造：按 \\(z_t\\) 缩放因子暴露（波动目标、估值信号），可行性与成本另见<a href="/quant/factor-timing-feasibility">因子择时的可行性</a>。</p><p><span class="marginnote">数字实例：设 \\(z_t\\) 是取 0 到 1 的风险厌恶指标，市场因子月超额 \\(f_t\\)。交互因子 \\(z_t f_t\\) 在平静月（\\(z=0.2\\)）只记录 0.2 倍市场收益，在恐慌月（\\(z=1\\)）记录全额——它把「坏月份的市场」单独拎出来当一只新因子。若回归显示它的风险价格显著为正，说明坏月份里的市场风险确实更贵。</span></p>',10)),(t(),A(n,null,{default:E(()=>[i(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E7%8A%B6%E6%80%81%E5%8F%98%E9%87%8F%20z%EF%BC%88PIT%EF%BC%8C%E6%9C%9F%E5%88%9D%E5%B7%B2%E7%9F%A5%EF%BC%89%22%5D%20--%3E%20Q1%7B%22%E6%9D%A1%E4%BB%B6%E5%8C%96%E5%93%AA%E4%B8%80%E4%BE%A7%3F%22%7D%0A%20%20Q1%20--%3E%7C%E6%BA%A2%E4%BB%B7%E6%88%96%E6%9A%B4%E9%9C%B2%7C%20INT%5B%22%E4%BA%A4%E4%BA%92%E5%9B%A0%E5%AD%90%20z%C2%B7f%20%E8%BF%9B%E5%85%A5%E5%9B%A0%E5%AD%90%E9%9B%86%22%5D%0A%20%20Q1%20--%3E%7C%E8%BD%BD%E8%8D%B7%7C%20IP%5B%22IPCA%EF%BC%9A%E7%89%B9%E5%BE%81%E4%BD%9C%E4%B8%BA%E8%BD%BD%E8%8D%B7%E7%9A%84%E5%B7%A5%E5%85%B7%22%5D%0A%20%20INT%20--%3E%20FM%5B%22FM%2F%E6%97%B6%E5%BA%8F%E5%9B%9E%E5%BD%92%E6%A3%80%E9%AA%8C%E4%BA%A4%E4%BA%92%E9%A1%B9%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20IP%20--%3E%20FM%0A%20%20FM%20--%3E%20OOS%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E4%B8%8E%E5%A4%9A%E7%8A%B6%E6%80%81%E5%AD%90%E6%A0%B7%E6%9C%AC%E9%AA%8C%E8%AF%81%22%5D%0A%20%20OOS%20--%3E%20DEC%5B%22%E6%8E%A5%E5%8F%97%E6%9D%A1%E4%BB%B6%E8%AE%BE%E5%AE%9A%2F%E9%80%80%E5%9B%9E%E6%97%A0%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上三条纪律。第一，状态变量的可得性：\\(z_t\\) 必须在 \\(t\\) 期期初公开可得——发布滞后、修订与口径变化都要按 <a href="/quant/point-in-time">point-in-time</a> 处理，否则条件化是披着模型的未来函数（<a href="/quant/no-future-function">无未来函数</a>）。经典候选如 Lettau–Ludvigson 2001 的 \\(cay\\)（消费—财富—收入比），其价值在于状态变量的构造与检验是公开可复制的。第二，载荷条件化的工具化：<a href="/quant/ipca">IPCA</a> 把特征当作载荷的工具变量，让 β 随可观测特征演化，避免「先分状态再分组」的自由度爆炸。第三，验证协议：条件设定必须在样本外与多个状态子段上复验（<a href="/quant/walk-forward">walk-forward</a>），样本内显著的状态交互是多重检验的高危区。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么无条件检验的失真是系统性的？看协方差项：若 \\(\\mathrm{Cov}(\\beta_t,\\lambda_t)\\gt 0\\)——风险高的状态里风险厌恶也高——无条件 \\(\\alpha\\) 会系统性偏离；动量的条件结构（崩盘尾部集中在衰退后段，见<a href="/quant/momentum-crash">动量崩盘</a>）就是载荷时变与溢价时变叠加的例子。条件化的收益是把这项从「误差」变成「参数」：交互项显著意味着时变结构可预测，交互项不显著则支持无条件设定——两种结果都是信息。危险不在检验本身，在搜索：\\(z\\) 的候选空间近乎无限（宏观、情绪、估值、波动），试一百个 \\(z\\) 挑最显著的一个，等于把多重检验折价置之不理；<a href="/quant/pbo">PBO</a>、<a href="/quant/cscv">CSCV</a> 与状态变量的<a href="/quant/hypothesis-preregistration">预注册</a>在这里不是装饰，是必要条件。</p>',4)),(t(),A(n,null,{default:E(()=>[i(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%9D%8F%E7%8A%B6%E6%80%81%E5%88%B0%E6%9D%A5%3A%20%E9%A3%8E%E9%99%A9%E5%8D%87%E9%AB%98%22%5D%20--%3E%20S2%5B%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%E4%B8%8A%E5%8D%87%3Cbr%2F%3E%E6%BA%A2%E4%BB%B7%20%CE%BB%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20S1%20--%3E%20S3%5B%22%E9%AB%98%20%CE%B2%20%E8%B5%84%E4%BA%A7%E8%A2%AB%E6%8A%9B%E5%94%AE%3Cbr%2F%3E%E5%AE%9E%E9%99%85%E6%9A%B4%E9%9C%B2%20%CE%B2%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20S2%20--%3E%20COV%5B%22Cov(%CE%B2_t%2C%20%CE%BB_t)%20%E9%AB%98%E4%BA%8E%E9%9B%B6%22%5D%0A%20%20S3%20--%3E%20COV%0A%20%20COV%20--%3E%20U%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E6%A8%A1%E5%9E%8B%E5%8F%AA%E7%94%A8%3Cbr%2F%3E%E5%B9%B3%E5%9D%87%20%CE%B2%20%E4%B9%98%E5%B9%B3%E5%9D%87%20%CE%BB%22%5D%0A%20%20U%20--%3E%20RES%5B%22%E6%97%B6%E5%8F%98%E7%BB%93%E6%9E%84%E6%8E%89%E8%BF%9B%E6%AE%8B%E5%B7%AE%3Cbr%2F%3E%E8%A2%AB%E8%AE%B0%E6%88%90%E5%AE%9A%E4%BB%B7%E8%AF%AF%E5%B7%AE%20%CE%B1%22%5D%0A%20%20RES%20--%3E%20A1%5B%22%E5%81%87%E8%B1%A1%E4%B8%80%3A%3Cbr%2F%3E%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%9A%84%E5%9B%A0%E5%AD%90%E5%8F%98%E6%98%BE%E8%91%97%22%5D%0A%20%20RES%20--%3E%20A2%5B%22%E5%81%87%E8%B1%A1%E4%BA%8C%3A%3Cbr%2F%3E%E7%9C%9F%E5%9B%A0%E5%AD%90%E8%A2%AB%E6%8A%B9%E5%B9%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p><span class="marginnote">常见误区：初学者容易以为「多试几个状态变量，总能找到一个显著的交互项」是勤奋，其实是搜出来的显著性——100 个相互独立的候选 \\(z\\) 在 5% 水平下平均有 5 个纯靠运气「显著」。预注册、PBO 折价与样本外复验，就是给这扇后门上锁的三道工序。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>条件化不是免费午餐：每加一个交互项，样本的有效信息被摊薄，估计方差上升；状态变量之间的相关（估值与信用价差常同向）让交互项彼此难以区分。它也不解决因子择时的执行问题：即使交互项真实，按它调仓的成本与容量是另一门工程。最后，条件因子模型的报告必须附带状态变量的构造细节——本课程报告规范课对 \\(z\\) 同样适用：一个无法 PIT 复现的状态变量，足以推翻整个条件设定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无条件模型丢掉 \\(\\mathrm{Cov}(\\beta_t,\\lambda_t)\\)，时变被误记为定价误差。</li><li>管理组合技巧：交互因子 \\(z_t f_t\\) 把条件假设变成可检验回归。</li><li>状态变量必须期初可得（PIT），载荷条件化用 IPCA 类工具控制自由度。</li><li>条件化的主要风险是搜索 \\(z\\) 的多重检验，预注册与折价计算不可省。</li><li>出处：Cochrane, <em>Asset Pricing</em>, 2001；Lettau &amp; Ludvigson, <em>JPE</em>, 2001。</li></ul>',5))])}const c=o(d,[["render",_]]);export{D as __pageData,c as default};
